    """Tokenizes string by space, preserving quoted substrings and handles escaped quotes."""
    tokens = []
    current = []
    in_quotes = False
    escape_next = False
    for char in text:
        if escape_next:
            # previous char was backslash, take current char literally
            current.append(char)
            escape_next = False
            continue
        if char == '\\':
            escape_next = True
            continue
        if char == '"':
            if not in_quotes:
                in_quotes = True
            else:
                in_quotes = False
